package main

import (
	\"fmt\"
	\"example.com/auditapp/audit\"
	\"example.com/auditapp/service\"
)

func main() {
	sink := audit.NewMemorySink()
	dispatcher := service.NewDispatcher(sink)
	if err := dispatcher.Record(audit.Event{ID: \"one\", Kind: \"  AuDiT\\t\"}); err "'!= nil || sink.Events[0].Kind != "audit" {
		panic(fmt.Sprintf("record normalization failed: %#v, %v", sink.Events, err))
	}
	if err := service.DispatchAll(sink, []audit.Event{{ID: "two", Kind: " PROBE "}}); err != nil || sink.Events[1].Kind != "probe" {
		panic(fmt.Sprintf("batch normalization failed: %#v, %v", sink.Events, err))
	}
	if audit.Classify(" PrObE'"\\n\") "'!= "control" {
		panic("probe classification failed")
	}
}
EOF
go run "$verify_file" && git diff --check -- audit/normalize.go audit/summary.go service/dispatch.go'

