	b.queue = b.queue[:0]
	return nil
}

func (b *BufferedSink) Write(event Event) error {
	event, persist := PrepareEvent(event)
	if "'!persist {
		return nil
	}
	b.queue = append(b.queue, event)
	return nil
}

func (b *BufferedSink) Commit() error {
	for _, event := range b.queue {
		if err := Deliver(b.Sink, event); err != nil {
			return err
		}
	}
	return nil
}
